from collections import deque


def can_split(n: int, rivals: list[list[int]]) -> bool:
    adj = [[] for _ in range(n)]
    for a, b in rivals:
        adj[a].append(b)
        adj[b].append(a)
    team = [-1] * n
    for start in range(n):
        if team[start] != -1:
            continue
        team[start] = 0                          # a new group: its first player picks freely
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if team[v] == -1:
                    team[v] = 1 - team[u]        # a rival is forced onto the other team
                    queue.append(v)
                elif team[v] == team[u]:
                    return False
    return True

